dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "news",
      "header": "CFDE Knowledge Center News",
      "data point": {
        "type": "api",
        "url": "https://hugeampkpncms.org/rest/news?id=$id",
        "parameters": [
          "id"
        ],
        "parameters type": "replace",
        "data type": "json"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "News",
            "raw field": "title"
          },
          {
            "type": "raw",
            "field name": "Summary",
            "raw field": "body"
          }
        ],
        "top rows": [
          "News",
          "Summary"
        ]
      }
    }
  ]
}

